    runtime
        .register_worker(
            WorkerManifest::new("approval.gate", "0.1.0").function(FunctionSpec::new(
                "approval::request",
                CapabilityRisk::Approval,
            )),
        )
        .unwrap();
    runtime
        .register_worker(
            WorkerManifest::new("shell.sandbox", "0.1.0")
                .function(
                    FunctionSpec::new("shell::run", CapabilityRisk::Exec).approval_required(true),
                )
