#[test]
fn queue_lease_heartbeat_events_do_not_leak_secrets() {
    let mut supervisor =
        WorkerProcessSupervisor::new(heartbeat_invocation()).with_redaction_rules(vec![
            RedactionRule::literal("sk-live-123", "[api-key]"),
            RedactionRule::env_assignment("DATABASE_URL"),
        ]);

    supervisor.request_start();
    supervisor.mark_ready("ready");
    supervisor
        .record_queue_lease_heartbeat(&heartbeat_request(
            "agent.queue",
            60,
            json!({
                "detail": "sk-live-123 DATABASE_URL=postgres://user:pass@localhost/db",
                "token": "secret-token",
                "nested": {
                    "password": "super-secret",
                    "safe": "visible"
                }
            }),
        ))
        .expect("heartbeat is recorded");

    let event_json = serde_json::to_string(supervisor.events().last().unwrap()).unwrap();
    assert!(!event_json.contains("sk-live-123"));
    assert!(!event_json.contains("postgres://user:pass@localhost/db"));
    assert!(!event_json.contains("secret-token"));
    assert!(!event_json.contains("super-secret"));
    assert!(event_json.contains("[api-key]"));
    assert!(event_json.contains("[redacted]"));
}

#[test]
fn failures_restart_until_max_restarts_then_enter_failed_terminal_state() {
    let mut supervisor = WorkerProcessSupervisor::new(invocation());

    supervisor.request_start();
    supervisor.record_exit_failure(1, "first crash");
    supervisor.record_exit_failure(2, "second crash");
    supervisor.record_exit_failure(3, "third crash");

    assert_eq!(supervisor.state(), WorkerProcessState::Failed);
    assert_eq!(supervisor.restart_count(), 2);
    assert_eq!(
        supervisor.events(),
        &[
            WorkerProcessSupervisorEvent::StartRequested {
                sequence: 1,
                worker_id: "agent-memory".to_string(),
                attempt: 1,
                invocation: invocation(),
            },
            WorkerProcessSupervisorEvent::ExitFailure {
                sequence: 2,
                worker_id: "agent-memory".to_string(),
                attempt: 1,
                exit_code: 1,
                message: "first crash".to_string(),
            },
            WorkerProcessSupervisorEvent::RestartScheduled {
                sequence: 3,
                worker_id: "agent-memory".to_string(),
                next_attempt: 2,
                restart_count: 1,
                backoff_ms: 250,
            },
            WorkerProcessSupervisorEvent::StartRequested {
                sequence: 4,
                worker_id: "agent-memory".to_string(),
                attempt: 2,
                invocation: invocation(),
            },
            WorkerProcessSupervisorEvent::ExitFailure {
                sequence: 5,
                worker_id: "agent-memory".to_string(),
                attempt: 2,
                exit_code: 2,
                message: "second crash".to_string(),
            },
            WorkerProcessSupervisorEvent::RestartScheduled {
                sequence: 6,
                worker_id: "agent-memory".to_string(),
                next_attempt: 3,
                restart_count: 2,
                backoff_ms: 250,
            },
            WorkerProcessSupervisorEvent::StartRequested {
                sequence: 7,
                worker_id: "agent-memory".to_string(),
                attempt: 3,
                invocation: invocation(),
            },
            WorkerProcessSupervisorEvent::ExitFailure {
                sequence: 8,
                worker_id: "agent-memory".to_string(),
                attempt: 3,
                exit_code: 3,
                message: "third crash".to_string(),
            },
            WorkerProcessSupervisorEvent::Failed {
                sequence: 9,
                worker_id: "agent-memory".to_string(),
                attempt: 3,
                reason: "max restarts exceeded after 2 restarts".to_string(),
            },
        ]
    );
}

#[test]
fn graceful_stop_records_stop_policy_metadata_and_stopped_terminal_state() {
    let mut supervisor = WorkerProcessSupervisor::new(invocation());

    supervisor.request_start();
    supervisor.mark_ready("ready");
    supervisor.request_graceful_stop("operator requested shutdown");
    supervisor.mark_stopped(0, "process exited cleanly");

    assert_eq!(supervisor.state(), WorkerProcessState::Stopped);
    assert_eq!(
        supervisor.events(),
        &[
            WorkerProcessSupervisorEvent::StartRequested {
                sequence: 1,
                worker_id: "agent-memory".to_string(),
                attempt: 1,
                invocation: invocation(),
            },
            WorkerProcessSupervisorEvent::Ready {
                sequence: 2,
                worker_id: "agent-memory".to_string(),
                attempt: 1,
                readiness_probe: Some(ReadinessProbe::tcp("127.0.0.1", 3000).initial_delay_ms(100)),
                message: "ready".to_string(),
            },
            WorkerProcessSupervisorEvent::GracefulStopRequested {
                sequence: 3,
                worker_id: "agent-memory".to_string(),
                attempt: 1,
                stop_policy: StopPolicy::term_then_kill(1_500),
                reason: "operator requested shutdown".to_string(),
            },
            WorkerProcessSupervisorEvent::Stopped {
                sequence: 4,
                worker_id: "agent-memory".to_string(),
                attempt: 1,
                exit_code: 0,
                message: "process exited cleanly".to_string(),
            },
        ]
    );
}

use openview_worker::{
    ReadinessProbe, RedactionRule, RestartPolicy, StopPolicy, WorkerProcessRequest,
    WorkerProcessStdio, WorkerStdioStream,
};
use serde_json::json;

#[test]
fn worker_process_request_builds_secret_free_invocation_contract() {
    let request = WorkerProcessRequest::new("agent-memory", "agentmemory")
        .arg("serve")
        .arg("--port")
        .arg("3000")
        .working_directory("/repo/agentmemory")
        .env_key("OPENAI_API_KEY")
        .env_key("DATABASE_URL")
        .process_group(true)
        .readiness_probe(ReadinessProbe::tcp("127.0.0.1", 3000).initial_delay_ms(250))
        .restart_policy(RestartPolicy::on_failure(3).backoff_ms(500))
        .stop_policy(StopPolicy::term_then_kill(1_500));

    let invocation = request.invocation();

    assert_eq!(invocation.worker_id, "agent-memory");
    assert_eq!(invocation.binary, "agentmemory");
    assert_eq!(invocation.argv, vec!["serve", "--port", "3000"]);
    assert_eq!(
        invocation.working_directory.as_deref(),
        Some("/repo/agentmemory")
    );
    assert_eq!(invocation.env_keys, vec!["OPENAI_API_KEY", "DATABASE_URL"]);
    assert!(invocation.create_process_group);
    assert_eq!(
        invocation.readiness_probe,
        Some(ReadinessProbe::tcp("127.0.0.1", 3000).initial_delay_ms(250))
    );
    assert_eq!(
        invocation.restart_policy,
        RestartPolicy::on_failure(3).backoff_ms(500)
    );
    assert_eq!(invocation.stop_policy, StopPolicy::term_then_kill(1_500));

    let value = serde_json::to_value(&invocation).expect("invocation serializes");
    assert!(
        value.get("env").is_none(),
        "env values must never serialize"
    );
    assert!(
        value.get("environment").is_none(),
        "env maps must never serialize"
    );
}

#[test]
fn stdout_and_stderr_events_are_sanitized_with_deterministic_redaction_rules() {
    let rules = vec![
        RedactionRule::literal("sk-live-123", "[api-key]"),
        RedactionRule::env_assignment("DATABASE_URL"),
    ];

    let stdout = WorkerProcessStdio::event_payload(
        "agent-memory",
        WorkerStdioStream::Stdout,
        42,
        "ready with token sk-live-123",
        &rules,
    );
    let stderr = WorkerProcessStdio::event_payload(
        "agent-memory",
        WorkerStdioStream::Stderr,
        43,
        "DATABASE_URL=postgres://user:pass@localhost/db failed",
        &rules,
    );

    assert_eq!(
        stdout,
        json!({
            "worker_id": "agent-memory",
            "stream": "stdout",
            "sequence": 42,
            "text": "ready with token [api-key]",
            "redacted": true
        })
    );
    assert_eq!(
        stderr,
        json!({
            "worker_id": "agent-memory",
            "stream": "stderr",
            "sequence": 43,
            "text": "DATABASE_URL=[redacted] failed",
            "redacted": true
        })
    );
}

#[test]
fn defaults_are_safe_and_deterministic_for_process_launches() {
    let invocation = WorkerProcessRequest::new("approval-gate", "approval-worker").invocation();

    assert_eq!(invocation.argv, Vec::<String>::new());
    assert_eq!(invocation.env_keys, Vec::<String>::new());
    assert_eq!(invocation.working_directory, None);
    assert!(!invocation.create_process_group);
    assert_eq!(invocation.readiness_probe, None);
    assert_eq!(invocation.restart_policy, RestartPolicy::Never);
    assert_eq!(invocation.stop_policy, StopPolicy::term_then_kill(5_000));
}
